package com.cabbagecounter;

import java.util.Collections;
import java.util.Set;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(CabbageCounterConfig.GROUP)
public interface CabbageCounterConfig extends Config
{
	String GROUP = "cabbage-counter";
	String COUNTER = "counter";
	String COUNTED_TILES = "countedTiles";
	String SHOW_OVERLAY = "showOverlay";

	@ConfigItem(
		keyName = CabbageCounterConfig.SHOW_OVERLAY,
		name = "Show overlay",
		description = "Show the cabbage count on screen"
	)

	default boolean showOverlay()
	{
		return true;
	}

	@ConfigItem(
		keyName = CabbageCounterConfig.COUNTER,
		name = "",
		description = "",
		hidden = true
	)

	default int counter()
	{
		return 0;
	}

	@ConfigItem(
		keyName = CabbageCounterConfig.COUNTED_TILES,
		name = "",
		description = "",
		hidden = true
	)

	default Set<WorldPoint> countedTiles()
	{
		return Collections.emptySet();
	}
}

package com.cabbagecounter;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

@Slf4j
@Singleton
public class CabbageCounterOverlay extends OverlayPanel
{
	private final CabbageCounterConfig config;
	private final OverlayManager overlayManager;

	private volatile String cabbageCount = "0";

	@Inject
	private CabbageCounterOverlay(CabbageCounterConfig config, OverlayManager overlayManager)
	{
		this.config = config;
		this.overlayManager = overlayManager;

		this.setPosition(OverlayPosition.TOP_LEFT);
		this.setLayer(OverlayLayer.ABOVE_SCENE);
	}

	public void startUp()
	{
		this.cabbageCount = Integer.toString(this.config.counter());
		this.overlayManager.add(this);
	}

	public void shutDown()
	{
		this.overlayManager.remove(this);
	}

	public void setCabbageCount(String cabbageCount)
	{
		this.cabbageCount = cabbageCount;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		this.panelComponent.getChildren().add(TitleComponent.builder()
			.text("Cabbage Counter")
			.color(Color.GREEN)
			.build());

		this.panelComponent.getChildren().add(LineComponent.builder()
			.left("Cabbages:")
			.right(this.cabbageCount)
			.build());

		return super.render(graphics);
	}
}

package com.cabbagecounter;

import com.google.inject.Provides;
import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.ItemSpawned;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@Slf4j
@PluginDescriptor(
	name = "Cabbage Counter",
	description = "It counts cabbages.",
	tags = {"cabbage", "counter", "farming", "brassica"}
)
public class CabbageCounterPlugin extends Plugin
{
	private static final int CABBAGE_ITEM_ID = 1965;
	private static final int CABBAGE_OBJECT_ID = 1161;

	private final Set<WorldPoint> countedObjectTiles = new HashSet<>();

	@Inject
	private CabbageCounterConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private CabbageCounterOverlay overlay;

	@Override
	protected void startUp() throws Exception
	{
		this.updateOverlayVisibility();
		this.countedObjectTiles.addAll(this.config.countedTiles());
	}

	@Override
	protected void shutDown() throws Exception
	{
		this.overlay.shutDown();
		this.countedObjectTiles.clear();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		boolean wrongGroup = event.getGroup().equals(CabbageCounterConfig.GROUP) == false;
		if (wrongGroup)
		{
			return;
		}

		switch (event.getKey())
		{
			case CabbageCounterConfig.COUNTER:
				String newValue = event.getNewValue();
				this.overlay.setCabbageCount(newValue == null ? "0" : newValue);
				break;
			case CabbageCounterConfig.SHOW_OVERLAY:
				this.updateOverlayVisibility();
				break;
			default:
				break;
		}
	}



	@Subscribe
	public void onItemSpawned(ItemSpawned event)
	{
		boolean notCabbage = event.getItem().getId() != CABBAGE_ITEM_ID;
		if (notCabbage)
		{
			return;
		}

		this.incrementCounter();
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		boolean notCabbage = event.getGameObject().getId() != CABBAGE_OBJECT_ID;
		if (notCabbage)
		{
			return;
		}

		this.incrementCounter(event.getGameObject().getWorldLocation());
	}

	private void incrementCounter()
	{
		int currentCount = this.config.counter();
		this.configManager.setConfiguration(CabbageCounterConfig.GROUP, CabbageCounterConfig.COUNTER, currentCount + 1);
	}

	private void incrementCounter(WorldPoint tile)
	{
		boolean alreadyCounted = this.countedObjectTiles.add(tile) == false;
		if (alreadyCounted)
		{
			return;
		}

		this.incrementCounter();
		this.configManager.setConfiguration(CabbageCounterConfig.GROUP, CabbageCounterConfig.COUNTED_TILES,	this.countedObjectTiles);
	}

	private void updateOverlayVisibility()
	{
		if (this.config.showOverlay())
		{
			this.overlay.startUp();
		}
		else
		{
			this.overlay.shutDown();
		}
	}

	@Provides
	CabbageCounterConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CabbageCounterConfig.class);
	}
}

package com.cabbagecounter;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class CabbageCounterPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(CabbageCounterPlugin.class);
		RuneLite.main(args);
	}
}
